from pathlib import Path
import re
p=Path('src/AppDb.tsx');s=p.read_text()
s=s.replace('(["Overview","Monthly Plans","Daily Plans","Scan Events","Reports","Settings"] as Page[])','(["Overview","Monthly Plans","Daily Plans","Scan Events","Reports"] as Page[])')
s=s.replace('>+ QR</button>','>Add serials</button>')
s=s.replace('type Daily = { id:string; monthly_plan_id:string; production_date:string; line_id:string; shift_id:string; planned_quantity:number; target_per_hour:number; planned_hours:number; max_capacity_quantity:number; status:string; production_lines?:Line|Line[]; production_shifts?:Shift|Shift[] };','type Daily = { id:string; monthly_plan_id:string; production_date:string; line_id:string; shift_id:string; shift_start:string; shift_end:string; break_minutes:number; planned_quantity:number; target_per_hour:number; planned_hours:number; max_capacity_quantity:number; status:string; submitted_to_scan:boolean; locked_at:string|null; production_lines?:Line|Line[]; production_shifts?:Shift|Shift[] };')
s=s.replace('const [dailyPlan,setDailyPlan]=useState(""); const [dailyDate,setDailyDate]=useState(new Date().toISOString().slice(0,10)); const [dailyLine,setDailyLine]=useState(""); const [dailyShift,setDailyShift]=useState(""); const [dailyQty,setDailyQty]=useState("500"); const [dailyRate,setDailyRate]=useState("100"); const [manpower,setManpower]=useState("10");','const [dailyPlan,setDailyPlan]=useState(""); const [dailyDate,setDailyDate]=useState(new Date().toISOString().slice(0,10)); const [dailyLine,setDailyLine]=useState(""); const [dailyShift,setDailyShift]=useState(""); const [dailyQty,setDailyQty]=useState("500"); const [dailyRate,setDailyRate]=useState("100"); const [breakMinutes,setBreakMinutes]=useState("0"); const [manpower,setManpower]=useState("10"); const [actualManpower,setActualManpower]=useState("0");')
s=s.replace('production_date,line_id,shift_id,planned_quantity,target_per_hour,planned_hours,max_capacity_quantity,status,production_lines','production_date,line_id,shift_id,shift_start,shift_end,break_minutes,planned_quantity,target_per_hour,planned_hours,max_capacity_quantity,status,submitted_to_scan,locked_at,production_lines')
a=s.index(' async function saveDaily()'); b=s.index(' async function doScan()',a)
new=''' async function saveDaily(){if(!supabase||!session||!dailyPlan||!dailyLine||!dailyShift){setError("Select monthly plan, line and shift.");return}const sh=shifts.find(x=>x.id===dailyShift);const q=Number(dailyQty),rate=Number(dailyRate),productive=Math.max(0,hours(sh?.start_time||"08:00",sh?.end_time||"17:00")-(Number(breakMinutes)||0)/60),cap=Math.floor(productive*rate);if(!sh||!q||!rate){setError("Enter valid quantity and rate.");return}if(q>cap){setNotice(`Capacity warning: ${q.toLocaleString()} planned vs ${cap.toLocaleString()} maximum shift capacity.`)}const {data:p,error}=await supabase.from("daily_production_plans").insert({monthly_plan_id:dailyPlan,production_date:dailyDate,line_id:dailyLine,shift_id:dailyShift,shift_start:sh.start_time,shift_end:sh.end_time,break_minutes:Number(breakMinutes)||0,planned_quantity:q,target_per_hour:rate,planned_hours:productive,max_capacity_quantity:cap,status:"planned",created_by:session.user.id}).select("id").single();if(error||!p){setError(error?.message??"Daily plan failed");return}const m=await supabase.from("daily_plan_manpower").upsert({daily_plan_id:p.id,manpower_category:"production",manpower_count:Number(manpower)||0,actual_count:Number(actualManpower)||0},{onConflict:"daily_plan_id,manpower_category"});if(m.error){setError(m.error.message);return}const {data:ss}=await supabase.from("serial_registry").select("id").eq("monthly_plan_id",dailyPlan).limit(q);if(!ss||ss.length<q){setError(`Only ${ss?.length??0} serials are available for allocation.`);return}for(let i=0;i<ss.length;i+=500){const rows=ss.slice(i,i+500).map(x=>({daily_plan_id:p.id,serial_registry_id:x.id,created_by:session.user.id}));const r=await supabase.from("daily_plan_serials").insert(rows);if(r.error){setError(r.error.message);return}}setDailyOpen(false);await load();setNotice(`Daily plan created: ${q.toLocaleString()} planned · ${cap.toLocaleString()} max capacity.`)}
'''
s=s[:a]+new+s[b:]
s=s.replace('setNotice(`${r?.result??"SCAN"}: ${r?.message??"Processed"}`);setScan("");await load()','setNotice(`${r?.result??"SCAN"}: ${r?.message??"Processed"}`);if(r?.daily_plan_id)await supabase.from("daily_production_plans").update({submitted_to_scan:true,locked_at:new Date().toISOString(),locked_by:session.user.id,status:"running"}).eq("id",r.daily_plan_id).eq("submitted_to_scan",false);setScan("");await load()')
needle=' async function doScan()'
insert=''' async function sendToScan(d:Daily){if(!supabase||d.submitted_to_scan)return;const r=await supabase.from("daily_production_plans").update({submitted_to_scan:true,locked_at:new Date().toISOString(),locked_by:session?.user.id,status:"running"}).eq("id",d.id).eq("submitted_to_scan",false);if(r.error){setError(r.error.message);return}setScanLine(d.line_id);setScanShift(d.shift_id);setPage("Scan Events");await load();setNotice("Daily plan submitted to Scan Station and locked for editing.")}
'''
s=s.replace(needle,insert+needle)
s=s.replace('<td><button className="icon-button" onClick={()=>openEditDaily(d)}>Edit</button></td>','<td>{d.submitted_to_scan?<span className="locked-action">🔒 Locked</span>:<div className="daily-actions"><button className="button button-sm button-secondary" onClick={()=>openEditDaily(d)}>Edit plan</button><button className="button button-sm button-primary" onClick={()=>sendToScan(d)}>Send to scan</button></div>}</td>')
pattern=r'(<Field l="Target / hour">.*?</Field>)'
extra=r'''\1<Field l="Break / non-productive minutes"><input type="number" min="0" value={breakMinutes} onChange={e=>setBreakMinutes(e.target.value)}/></Field><Field l="Planned quantity"><input type="number" min="1" value={dailyQty} onChange={e=>setDailyQty(e.target.value)}/></Field><Field l="Manpower actually used"><input type="number" min="0" value={actualManpower} onChange={e=>setActualManpower(e.target.value)}/></Field>'''
s,n=re.subn(pattern,extra,s,count=1,flags=re.S)
s=s.replace('Quantity cannot exceed the selected shift capacity.','A plan can be larger than one shift capacity; the system shows the capacity gap and keeps the pending balance visible.')
p.write_text(s)
print('patched',n)
